"""Per-key token bucket replayed over a timeline of events. See task.md."""

from __future__ import annotations

import math
from fractions import Fraction
from typing import NamedTuple


class ConfigError(ValueError):
    """Raised for an unusable config and for an unusable event stream."""


class Event(NamedTuple):
    timestamp_ms: int
    key: str
    cost: int


class Decision(NamedTuple):
    allowed: bool
    remaining: int
    retry_after_ms: int


def decide(config: dict, events: list[Event]) -> list[Decision]:
    """Replay `events` through a per-key token bucket, one Decision each."""
    for name in ("capacity", "refill_tokens", "refill_interval_ms"):
        if name not in config:
            raise ConfigError(f"missing config key: {name}")
    capacity = config["capacity"]
    refill_tokens = config["refill_tokens"]
    refill_interval_ms = config["refill_interval_ms"]
    if capacity < 1:
        raise ConfigError("capacity must be at least 1")
    if refill_tokens < 1:
        raise ConfigError("refill_tokens must be at least 1")
    if refill_interval_ms < 1:
        raise ConfigError("refill_interval_ms must be at least 1")
    initial_tokens = config.get("initial_tokens", capacity)
    if not 0 <= initial_tokens <= capacity:
        raise ConfigError("initial_tokens must be between 0 and capacity")

    rate = Fraction(refill_tokens, refill_interval_ms)
    buckets: dict[str, tuple[Fraction, int]] = {}
    decisions: list[Decision] = []
    previous_t: int | None = None

    for t, key, cost in events:
        if cost < 0:
            raise ConfigError(f"negative cost: {cost}")
        if previous_t is not None and t < previous_t:
            raise ConfigError("events are not sorted by timestamp_ms")
        previous_t = t

        bucket = buckets.get(key)
        if bucket is None:
            tokens = Fraction(initial_tokens)
        else:
            held, last_t = bucket
            tokens = min(Fraction(capacity), held + (t - last_t) * rate)

        if cost > capacity:
            allowed, retry_after_ms = False, -1
        elif tokens >= cost:
            tokens -= cost
            allowed, retry_after_ms = True, 0
        else:
            allowed = False
            retry_after_ms = math.ceil((cost - tokens) / rate)

        buckets[key] = (tokens, t)
        decisions.append(Decision(allowed, math.floor(tokens), retry_after_ms))

    return decisions
